// Two generators share this file, because the parity fixture namespace "ui" must be generated by parity/gen/ui.gen.ts:
//
//   node --import tsx parity/gen/ui.gen.ts     parity fixtures for src/ui.ts (fixtures/parity/ui/), recorded at the end
//   npm run build && node --import tsx parity/gen/ui.gen.ts --screens [--out <dir>] [--only <scenario>[,..]] [--print]
//                                              the UI screen goldens (fixtures/ui); the rest of this comment is about them
//
// UI screen goldens: regenerates fixtures/ui from the TS app.
//
// Drives `node dist/cli.js` in a real PTY (130x36, TERM=xterm-256color) with an isolated DECKHAND_HOME and HOME under
// $TMPDIR and the fake agents of tests/helpers.ts, renders with @xterm/headless, and writes <nn>-<name>.txt/.json for
// every screen plus README.md (normalisations and key scripts). Output is deterministic: run it twice, diff is empty.
import fs from 'node:fs/promises';
import path from 'node:path';
import type {Screen, Step} from './ui/harness.ts';

const SCREENS = process.argv.includes('--screens');
// The PTY harness (node-pty, xterm, tests/helpers.ts) is loaded only for --screens.
const {CLI, PROJECT, Session} = SCREENS ? await import('./ui/harness.ts') : {} as typeof import('./ui/harness.ts');
const {RULES} = SCREENS ? await import('./ui/normalise.ts') : {} as typeof import('./ui/normalise.ts');
const {SCENARIOS} = SCREENS ? await import('./ui/scenarios.ts') : {} as typeof import('./ui/scenarios.ts');

const args = process.argv.slice(2);
const option = (name: string) => { const at = args.indexOf(name); return at >= 0 ? args[at + 1] : undefined; };
const only = option('--only')?.split(',');
const print = args.includes('--print');
// A partial run (--only) never writes over the full set unless --out says where.
const out = !SCREENS ? undefined : option('--out') ? path.resolve(option('--out')!) : only ? undefined : path.join(PROJECT, 'fixtures', 'ui');

function describeKey(key: string): string {
	const names: Record<string, string> = {'\x1b': 'Esc', '\r': 'Enter', '\t': 'Tab', '\x1b[Z': 'Shift+Tab', '\x7f': 'Backspace', '\x1b[A': 'Up', '\x1b[B': 'Down', '\x1b[C': 'Right', '\x1b[D': 'Left', '\x1b[H': 'Home', '\x1b[F': 'End', ' ': 'Space'};
	if (names[key]) return names[key]!;
	if (key.length === 1 && key.charCodeAt(0) < 32) return `Ctrl+${String.fromCharCode(key.charCodeAt(0) + 64)}`;
	return JSON.stringify(key);
}

function describeStep(step: Step): string {
	if ('press' in step) return describeKey(step.press);
	if ('wait' in step) return `⟨wait ${JSON.stringify(step.wait)}⟩`;
	if ('waitGone' in step) return `⟨wait gone ${JSON.stringify(step.waitGone)}⟩`;
	if ('resize' in step) return `⟨resize ${step.resize.cols}x${step.resize.rows}⟩`;
	return `⟨${step.external} ${JSON.stringify(step.args)}⟩`;
}

function readme(screens: Array<Screen & {file: string}>): string {
	const lines = [
		'# UI screen goldens',
		'',
		'Generated by `parity/gen/ui.gen.ts` from the TS (Ink) app; do not edit by hand. Regenerate with',
		'`npm run build && node --import tsx parity/gen/ui.gen.ts` (it rewrites this directory, README included).',
		'',
		'## Files',
		'',
		'- `<nn>-<name>.txt`: the screen rows exactly as displayed after normalisation, trailing spaces trimmed (one line per',
		'  terminal row, so a screen always has `rows` lines).',
		'- `<nn>-<name>.json`: `{name, scenario, cols, rows, keys, script, text, cursor, styles}`.',
		'  - `keys`: every key written to the PTY since the app started, in order (raw bytes as JSON strings).',
		'  - `script`: the replayable steps from the start: `{press}`, `{wait: text}` (wait until the normalised screen',
		'    contains it), `{waitGone: text}`, `{resize: {cols, rows}}` (PTY and terminal both), `{external, args}` (below).',
		'    After the last step the harness waits for idle (the normalised screen unchanged for 700 ms) and captures.',
		'  - `text`: the normalised rows (same as the .txt).',
		'  - `cursor`: `{x, y, visible}` (0-based; `visible` is DECTCEM, Ink hides it).',
		'  - `styles`: per row, the runs of cells whose style is not the default: `{start, end}` (display columns of the',
		'    normalised row, end exclusive) plus only the attributes that are set: `fg`/`bg` (palette index 0-255, or',
		'    `#rrggbb` for true colour), `bold`, `dim`, `italic`, `underline`, `inverse`. Rows without such runs are omitted.',
		'',
		'## Environment',
		'',
		'Each scenario starts a fresh app: `node dist/cli.js` (no arguments) in a real PTY, 130x36, `TERM=xterm-256color`,',
		'cwd `<TMP>/demo`, where `<TMP>` is `realpath($TMPDIR)/dh-ui-XXXXXX` (removed afterwards) holding:',
		'',
		'- `home/`: `DECKHAND_HOME` (the daemon the UI starts lives here; worktrees go to `home/worktrees/<name>`).',
		'- `user/`: `HOME`; `CLAUDE_CONFIG_DIR=user/.claude`, `CODEX_HOME=user/.codex`.',
		'- `bin/`: `claude`, `pi`, `codex` = the `fakeAgent` of tests/helpers.ts; `deckhand-cli.mjs` = a shim importing',
		'  dist/cli.js, which is `TEST_CLI` (the fake agents report hooks with `node $TEST_CLI hook`).',
		'- `demo/`: a git repo (`git init -b main`, user `Deckhand Test <deckhand@example.invalid>`, gpgsign off, hooks off)',
		'  with one commit "initial" of `file.txt` (`first\\n`), `README.md` (`# Demo\\n\\nA repository for UI goldens.\\n`)',
		'  and `deckhand.json` (`{"devCommand": "echo dev-ready", "actions": {"test": "echo tests-ok"}}`, 2-space JSON).',
		'',
		'The environment is exactly: `PATH=<TMP>/bin:<node dir>:<git dir>:/usr/bin:/bin:/usr/sbin:/sbin`, `HOME`,',
		'`DECKHAND_HOME`, `DECKHAND_DEV=0`, `DECKHAND_AGENT_LATEST={}`, `SHELL=/bin/sh`, `TERM=xterm-256color`,',
		'`LANG=en_US.UTF-8`, `TZ=UTC`, `USER=LOGNAME=deckhand`, `TEST_CLI`, `CLAUDE_CONFIG_DIR`, `CODEX_HOME`,',
		'`EDITOR=VISUAL=true`, `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1`, and `TMPDIR` when set.',
		'',
		'External steps (`{external, args}`) are changes made outside the UI at that point of the script:',
		'',
		'- `hook {session, payload}`: what the fake agent of the session titled `session` would send: runs',
		'  `node $TEST_CLI hook` with that session\'s `DECKHAND_SESSION_ID`, `DECKHAND_LAUNCH_ID`, `DECKHAND_HOOK_TOKEN`',
		'  (from `home/trace-<id>.json`) and stdin `{"session_id": <its native id>, ...payload}` (the native id is the',
		'  `--session-id`/`--resume` argument the fake claude got).',
		'- `write-file {path, content}`: writes the file (`<TMP>` expanded).',
		'- `git {cwd, args, env}`: runs `git -C <cwd> <args>` with `env` added (fixed commit dates, so the commits are the',
		'  same every run) and `GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1`.',
		'',
		'## Normalisations',
		'',
		'Applied in this order to every row before it is stored or compared; each rule rescans the row after a replacement.',
		'A replacement keeps the row\'s display width: the difference in columns is inserted into (or taken out of, keeping',
		'at least one space between words) the whitespace right after the word the replacement ends in. A replaced span takes',
		'the style of its first cell. Matching is on the row text (wide characters are one character).',
		'',
		'| # | rule | pattern | replacement |',
		'|---|------|---------|-------------|',
		'| 1 | temp path | `realpath($TMPDIR)/dh-ui-XXXXXX` (also without the `/private` prefix) | `<TMP>` |',
		...RULES.map((rule, index) => `| ${index + 2} | ${rule.name} | \`${String(rule.pattern).replace(/\|/g, '\\|')}\` | \`${rule.replace}\` |`),
		'',
		'Waits for idle make the rest stable: every created session is awaited until its agent is idle (no spinner), and',
		'transient status messages are awaited away (`waitGone`) before a screen that must not show them.',
		'',
		'## Screens',
		'',
	];
	let scenario = '';
	for (const screen of screens) {
		if (screen.scenario !== scenario) {
			scenario = screen.scenario;
			lines.push(...lines.at(-1) === '' ? [] : [''], `### Scenario \`${scenario}\``, '', SCENARIOS.find(item => item.name === scenario)!.about, '');
		}
		const previous = screens.filter(item => item.scenario === scenario && item.script.length < screen.script.length).at(-1);
		const from = previous ? previous.script.length : 0;
		lines.push(`- **${screen.file}** (${screen.cols}x${screen.rows})${previous ? ` after ${previous.file}` : ' from start'}: ${screen.script.slice(from).map(describeStep).join(' ') || '(no keys)'}`);
	}
	lines.push('');
	return lines.join('\n');
}

/** Pretty JSON with one array element per line for the long arrays (rows, style runs, keys, steps), compact inside. */
function screenJson(screen: Screen): string {
	const lines = Object.entries(screen).map(([key, value]) => (Array.isArray(value)
		? `\t${JSON.stringify(key)}: [${value.length ? `\n${value.map(item => `\t\t${JSON.stringify(item)}`).join(',\n')}\n\t` : ''}]`
		: `\t${JSON.stringify(key)}: ${JSON.stringify(value)}`));
	return `{\n${lines.join(',\n')}\n}\n`;
}

async function main(): Promise<void> {
	await fs.access(CLI).catch(() => { throw new Error('Build first: npm run build'); });
	const screens: Array<Screen & {file: string}> = [];
	for (const scenario of SCENARIOS) {
		if (only && !only.includes(scenario.name)) continue;
		const session = new Session(scenario.name);
		try {
			await session.start();
			await scenario.run(session);
		} finally {
			await session.stop();
			// A failed scenario still shows what it captured (--print), before the error.
			if (print) for (const screen of session.screens) console.log(`===== ${screen.scenario}/${screen.name}\n${screen.text.join('\n')}`);
		}
		for (const screen of session.screens) {
			const file = `${String(screens.length + 1).padStart(2, '0')}-${screen.name}`;
			screens.push({...screen, file});
		}
		console.error(`${scenario.name}: ${session.screens.length} screens`);
	}
	if (!out) return;
	await fs.mkdir(out, {recursive: true});
	for (const name of await fs.readdir(out)) if (/^\d+-.*\.(txt|json)$/.test(name)) await fs.rm(path.join(out, name));
	for (const {file, ...screen} of screens) {
		await fs.writeFile(path.join(out, `${file}.txt`), `${screen.text.join('\n')}\n`);
		await fs.writeFile(path.join(out, `${file}.json`), screenJson(screen));
	}
	await fs.writeFile(path.join(out, 'README.md'), readme(screens));
	console.error(`wrote ${screens.length} screens to ${path.relative(PROJECT, out) || '.'}`);
}

if (SCREENS) main().catch(error => { console.error(error instanceof Error ? error.stack ?? error.message : error); process.exitCode = 1; });
else await recordParityFixtures();

// ---------------------------------------------------------------------------------------------------------------
// Parity fixtures: fixtures/parity/ui/<fn>.jsonl for the pure helpers of src/ui.ts.
// ---------------------------------------------------------------------------------------------------------------
async function recordParityFixtures(): Promise<void> {
	const {Recorder, arb, encode, fc, installDeterminism, sample} = await import('../lib.ts');
	const ui = await import('../../src/ui.ts');
	installDeterminism();
	const recorder = new Recorder('ui', {cap: 1500});
	// Results with a lone surrogate (a cut inside a surrogate pair) cannot exist as Rust strings: not recorded.
	const rec = (name: string, fn: Function, argList: unknown[]) => {
		let result: unknown;
		try { result = fn(...argList); } catch { result = undefined; }
		if (!JSON.stringify(encode(result)).includes('$utf16')) recorder.call(name, fn, argList);
	};

	// Constants, recorded as zero-argument calls.
	recorder.call('THEME', () => ui.THEME, []);
	recorder.call('DISPLAY_CONTROL_PATTERN', () => ui.DISPLAY_CONTROL_PATTERN, []);

	// errorMessage: Error instances and primitives.
	class CustomError extends Error { constructor(message: string) { super(message); this.name = 'CustomError'; } }
	for (const value of [new Error('boom'), new TypeError('bad type'), new Error(''), new CustomError('custom 😀 中'), new Error('multi\nline'),
		'plain string', '', 'é😀', 42, 0, -1, 1.5, 1e21, 0.1 + 0.2, Number.NaN, Infinity, -Infinity, true, false, null, undefined]) recorder.call('errorMessage', ui.errorMessage, [value]);

	// Terminal text. Alphabet: escapes, CSI/OSC pieces, C0/C1 controls, tab, newline, CR, unicode.
	const terminalAlphabet = ['a', 'Z', ' ', '\u001b', '[', ']', '\\', '\u0007', '\r', '\n', '\t', '0', ';', 'm', 'K', '?', '/', '@', '~', '\u0000', '\u0008', '\u000b', '\u001f', '\u007f', '\u0080', '\u009f', ' ', 'é', '😀', '中'];
	const terminalCases = [
		'', 'plain', '\u001b[31mred\u001b[0m', '\u001b[1;38;5;196mbold\u001b[m', '\u001b[?25l\u001b[2Jx', '\u001b]0;title\u0007text', '\u001b]8;;https://e.x\u001b\\link\u001b]8;;\u001b\\',
		'\u001b]unterminated', '\u001b', '\u001b[', '\u001b[31', '\u001bM', '\u001bc', '\u001b_', 'a\u001b\\b', 'tab\tsep', 'line1\nline2', 'cr\roverwrite', 'one\r\ntwo\r\n', 'abc\r\rdef\r', 'x\r', '\rx', 'progress 10%\rprogress 100%\n',
		'\u0000\u0001\u0008\u000b\u000c\u001f\u007f\u0080\u0085\u009f ', 'wide 中文 and emoji 😀 and é', '\u001b[38;2;1;2;3mtrue\u001b[0m\t\n', '\n\n\n', '\t\t', '  ', '\u001b[2K\r$ ls\r\nfile  \u001b[34mdir\u001b[0m\r\n',
	];
	for (const text of [...terminalCases, ...sample(arb.text(30, terminalAlphabet), 250, 11)]) {
		recorder.call('stripTerminalControls', ui.stripTerminalControls, [text]);
		recorder.call('plainTerminalText', ui.plainTerminalText, [text]);
	}
	for (const text of sample(arb.text(40, [...terminalAlphabet, '\n', '\r', '\n', '\r']), 150, 12)) recorder.call('plainTerminalText', ui.plainTerminalText, [text]);

	// truncate / fitLines: widths are UTF-16 code units.
	const textCases = ['', 'a', 'ab', 'abc', 'hello world', 'é', '😀', '😀😀😀', '中文字符', 'a😀b', 'éé', 'x‍y', 'line\nbreak'];
	for (const text of textCases) for (const width of [-3, -1, 0, 1, 2, 3, 4, 5, 8, 11, 12, 13, 40, 1000]) rec('truncate', ui.truncate, [text, width]);
	for (const text of sample(arb.text(30), 300, 13)) for (const width of sample(fc.integer({min: -2, max: 35}), 2, text.length + 1)) rec('truncate', ui.truncate, [text, width]);
	const lineTexts = ['', 'one', 'one\ntwo', 'one\ntwo\nthree\nfour', '\n', '\n\n', 'a\n\nb', 'trailing\n', 'wide 中文字符 line\n😀😀😀😀', 'x'.repeat(50) + '\nshort'];
	for (const text of lineTexts) for (const width of [-1, 0, 1, 2, 5, 10, 80]) for (const height of [0, 1, 2, 3, 5]) rec('fitLines', ui.fitLines, [text, width, height]);
	for (const text of sample(arb.text(40), 200, 14)) {
		const [width, height] = sample(fc.tuple(fc.integer({min: -1, max: 30}), fc.integer({min: 0, max: 6})), 1, text.length + 5)[0]!;
		rec('fitLines', ui.fitLines, [text, width, height]);
	}

	// compactPath: without HOME, and compactPathHome with an explicit one ([home, path, width]; '' means no tilde).
	const withHome = (home: string | undefined, pathValue: string, width: number): string => {
		const saved = process.env.HOME;
		if (home === undefined) delete process.env.HOME; else process.env.HOME = home;
		try { return ui.compactPath(pathValue, width); } finally { if (saved === undefined) delete process.env.HOME; else process.env.HOME = saved; }
	};
	const compactPath = (pathValue: string, width: number): string => withHome(undefined, pathValue, width);
	const compactPathHome = (home: string, pathValue: string, width: number): string => withHome(home, pathValue, width);
	const paths = ['', '/', '/a', '/a/b', '/a/b/c', '/a/b/c/d/e', '/very/long/path/to/some/project/file.txt', 'relative/dir/file', 'relative', '//a//b//', '/a/b/', '/中文/目录/文件.txt', '/😀/é/x', '/tmp/x y/z'];
	for (const pathValue of paths) for (const width of [0, 1, 2, 3, 5, 10, 15, 20, 40, 100]) rec('compactPath', compactPath, [pathValue, width]);
	for (const [pathValue, width] of sample(fc.tuple(arb.text(30, ['a', 'b', '/', '/', '/', '中', '😀', 'é', ' ', '.']), fc.integer({min: 0, max: 40})), 200, 15)) rec('compactPath', compactPath, [pathValue, width]);
	const homePaths = ['', '/Users/tester', '/Users/tester/', '/Users/tester/code/app', '/Users/tester/a/b/c/d/e/f', '/Users/testers/x', '/Users/testerX', '/home/dev/projects/deckhand/src/ui.ts', '/home/dev', '/home/devel/x', '/tmp/other', '/Users/中文/项目/文件', '/x/y', '/abc', 'Users/tester/x'];
	for (const home of ['/Users/tester', '/home/dev', '/', '/Users/中文', '']) for (const pathValue of homePaths) for (const width of [0, 1, 2, 4, 8, 12, 20, 60]) rec('compactPathHome', compactPathHome, [home, pathValue, width]);

	// programGlyph / statusGlyph / statusColor / statusLabel.
	for (const program of ['claude', 'pi', 'codex']) recorder.call('programGlyph', ui.programGlyph, [program]);
	const statuses = ['starting', 'running', 'exited'] as const;
	const attentionStates = [undefined, 'unknown', 'working', 'needs-input', 'response-ended', 'failed', 'limited'] as const;
	const agentStatuses = [undefined, 'unknown', 'active', 'idle'] as const;
	const exitReasons = [undefined, 'stopped', 'failed', 'completed', 'interrupted'] as const;
	const replyReads = [undefined, true, false] as const;
	const setups = [undefined, 'pending', 'running', 'failed', 'cancelled', 'complete'] as const;
	interface Over { title?: string; status: typeof statuses[number]; attention?: typeof attentionStates[number]; agentStatus?: typeof agentStatuses[number]; exitReason?: typeof exitReasons[number]; replyRead?: boolean; cleanupError?: string; setup?: typeof setups[number]; id?: string; parentSessionId?: string }
	const session = (over: Over): Record<string, unknown> => {
		const record: Record<string, unknown> = {id: over.id ?? 's1', title: over.title ?? 'Session', program: 'claude', command: 'claude', cwd: '/repo', repoRoot: '/repo', status: over.status, createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:00:00.000Z'};
		if (over.agentStatus) record.agentStatus = over.agentStatus;
		if (over.parentSessionId !== undefined) record.parentSessionId = over.parentSessionId;
		if (over.attention) record.attention = {state: over.attention, event: 'Event', at: '2026-01-01T00:00:00.000Z'};
		if (over.replyRead !== undefined) record.replyRead = over.replyRead;
		if (over.exitReason) record.exitReason = over.exitReason;
		if (over.cleanupError !== undefined) record.cleanupError = over.cleanupError;
		if (over.setup) record.setup = {command: 'make', state: over.setup, output: ''};
		return record;
	};
	for (const status of statuses) for (const attention of attentionStates) for (const replyRead of replyReads) for (const agentStatus of agentStatuses) for (const exitReason of exitReasons) {
		recorder.call('statusGlyph', ui.statusGlyph, [session({status, attention, replyRead, agentStatus, exitReason}), '⠋']);
		if (replyRead === undefined) for (const cleanupError of [undefined, 'cannot remove']) recorder.call('statusColor', ui.statusColor, [session({status, attention, agentStatus, exitReason, cleanupError})]);
	}
	for (const frame of ['⠙', '', '*', '😀']) for (const status of statuses) for (const attention of ['working', 'needs-input', undefined] as const) recorder.call('statusGlyph', ui.statusGlyph, [session({status, attention, agentStatus: 'active'}), frame]);
	recorder.call('statusLabel', ui.statusLabel, [undefined]);
	const statusArb = fc.record({status: fc.constantFrom(...statuses), attention: fc.constantFrom(...attentionStates), agentStatus: fc.constantFrom(...agentStatuses), exitReason: fc.constantFrom(...exitReasons), replyRead: fc.constantFrom(...replyReads), setup: fc.constantFrom(...setups)});
	for (const over of sample(statusArb, 450, 16)) recorder.call('statusLabel', ui.statusLabel, [session(over)]);
	for (const status of statuses) for (const setup of setups) recorder.call('statusLabel', ui.statusLabel, [session({status, setup})]);
	for (const attention of attentionStates) for (const replyRead of replyReads) recorder.call('statusLabel', ui.statusLabel, [session({status: 'running', attention, replyRead, agentStatus: 'idle'})]);
	for (const exitReason of exitReasons) recorder.call('statusLabel', ui.statusLabel, [session({status: 'exited', exitReason, attention: 'failed'})]);

	// displaySessionTitle(session, sessions): parent prefixes, whitespace, slashes.
	const titleAlphabet = ['a', 'b', 'Parent', ' ', ' ', '  ', '/', '/', ' / ', '\t', '\n', ' ', ' ', 'é', '😀', '中'];
	const titles = [...sample(arb.text(12, titleAlphabet), 200, 17), '', ' ', '  padded  ', 'Parent / Child', 'Parent / Child / Grand', 'a  /  b', 'a/b', ' / ', '/', 'x\ty\nz', '中 / 文'];
	const make = (title: string, parent?: string, id = 's1'): Record<string, unknown> => session({status: 'running', title, id, ...(parent !== undefined ? {parentSessionId: parent} : {})});
	const other = make('Other', undefined, 'o');
	const parentTitles = ['Parent', '  Par  ent ', '', 'a', 'a b', '中'];
	for (const title of titles) {
		for (const parentTitle of parentTitles.slice(0, 1 + (title.length % 3))) {
			const parent = make(parentTitle, undefined, 'p');
			recorder.call('displaySessionTitle', ui.displaySessionTitle, [make(title), [make(title), other]]);
			recorder.call('displaySessionTitle', ui.displaySessionTitle, [make(title, 'p'), [other, parent, make(title, 'p')]]);
			recorder.call('displaySessionTitle', ui.displaySessionTitle, [make(`${parentTitle.trim().replace(/\s+/g, ' ')} / ${title}`, 'p'), [parent]]);
		}
		recorder.call('displaySessionTitle', ui.displaySessionTitle, [make(title, 'gone'), [other]]);
	}
	for (const [title, parentTitle] of [['Parent / Child', 'Parent'], ['Parent  /  Child', ' Parent '], ['Parent / ', 'Parent'], ['Parent', 'Parent'], ['Parent / Parent / Parent', 'Parent'], ['Parent/Child', 'Parent']] as const) {
		recorder.call('displaySessionTitle', ui.displaySessionTitle, [make(title, 'p'), [make(parentTitle, undefined, 'p')]]);
	}

	await recorder.write({prune: true});
}
